package com.bank.loan;

import java.math.BigDecimal;
import java.util.logging.*;

public class CircuitBreakerDemo {
    private static final Logger log = Logger.getLogger(CircuitBreakerDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws InterruptedException {
        CibilClient cibil = new CibilClient();
        CircuitBreaker breaker = new CircuitBreaker(3, 2000); // trip after 3 fails, 2s reset
        LoanService loanService = new LoanService(cibil, breaker);

        log.info("=== CIBIL healthy: Rajesh applies ===");
        loanService.evaluate("SAV2001", new BigDecimal("300000"));

        log.info("=== CIBIL goes DOWN ===");
        cibil.setDown(true);
        for (int i = 1; i <= 4; i++) {
            loanService.evaluate("CUR3001", new BigDecimal("300000"));
        }

        log.info("=== Breaker now OPEN: fast-fail fallback ===");
        loanService.evaluate("CUR3001", new BigDecimal("300000"));

        log.info("=== Wait for reset, CIBIL recovers ===");
        Thread.sleep(2200);
        cibil.setDown(false);
        loanService.evaluate("SAV2001", new BigDecimal("300000")); // half-open trial
    }
}

